  getNodeLabelRelativeY(node, forSvgTextRenderer = false) {
    const labelHeight = getNodeLabelHeight(node, this.appService.config());
    const relativeY = getNodeLabelYPadding(node, this.appService.config()) + labelHeight / 2 + 1;
    if (forSvgTextRenderer) {
      return this.webglRendererThreejsService.convertZFromSceneToScreen(relativeY);
    }
    return relativeY;
  }
  getNodeLabelSizes(node) {
    const nodeLabelHeight = getNodeLabelHeight(node, this.appService.config());
    const scale = nodeLabelHeight / this.texts.getFontSize();
    let minX = Number.POSITIVE_INFINITY;
    let maxX = Number.NEGATIVE_INFINITY;
    let firstLineLabelHeight = 0;
    const lines = splitLabel(this.getNodeLabel(node));
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const labelSize = this.texts.getLabelSizes(line, FontWeight.BOLD, nodeLabelHeight).sizes;
      minX = Math.min(minX, labelSize.minX);
      maxX = Math.max(maxX, labelSize.maxX);
      if (i === 0) {
        firstLineLabelHeight = (labelSize.maxZ - labelSize.minZ) * scale;
      }
    }
    return { minX, maxX, firstLineLabelHeight };
  }
  getNodeLabelColor(node) {
    let color2 = isGroupNode(node) ? this.getGroupNodeTextColor(node, ColorVariable.ON_SURFACE_COLOR) : new THREE16.Color(this.visualizerThemeService.getColor(ColorVariable.ON_SURFACE_COLOR));
    if (isOpNode(node) && node.style?.textColor) {
      color2 = new THREE16.Color(node.style.textColor);
    }
    for (const rule of this.curProcessedNodeStylerRules) {
      if (matchNodeForQueries(node, rule.queries, this.curModelGraph, this.appService.config())) {
        const nodeStylerTextColor = getNodeStyleValue(rule, NodeStyleId.NODE_TEXT_COLOR);
        if (nodeStylerTextColor !== "") {
          color2 = new THREE16.Color(nodeStylerTextColor);
        }
        break;
      }
    }
    return color2;
  }
