function heatColor(ratio) {
  if (ratio >= 0.85)
    return "#ff4d4d";
  if (ratio >= 0.65)
    return "#ff9f40";
  if (ratio >= 0.4)
    return "#ffd666";
  return "#fff3bf";
}
